import java.sql.*;
import java.util.logging.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Input validation - dates must match pattern
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        // Allowlist for report types
        if (reportType == null || !reportType.matches("(summary|detail|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - department and sortCol are used in dynamic SQL
        StringBuilder query = new StringBuilder();
        query.append("SELECT emp_id, emp_name, department, hours_worked, pay_rate ");
        query.append("FROM payroll_reports WHERE report_type = ? ");
        query.append("AND report_date BETWEEN ? AND ? ");

        // Department filter - appears sanitized but isn't fully
        if (department != null && !department.isEmpty()) {
            // Only allow alphanumeric and spaces... but underscore and percent slip through
            if (department.matches("[a-zA-Z0-9_ %]+")) {
                query.append("AND department = '").append(department).append("' ");
            }
        }

        // Sort column - vulnerable to injection via ORDER BY
        if (sortCol != null && !sortCol.isEmpty()) {
            // Developer thought this regex was sufficient
            if (sortCol.matches("[a-zA-Z_]+")) {
                query.append("ORDER BY ").append(sortCol);
            } else {
                query.append("ORDER BY emp_id");
            }
        } else {
            query.append("ORDER BY emp_id");
        }

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(query.toString())) {

            pstmt.setString(1, reportType);
            pstmt.setString(2, startDate);
            pstmt.setString(3, endDate);

            ResultSet rs = pstmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":\"%s\",\"name\":\"%s\",\"dept\":\"%s\",\"hours\":%.2f,\"rate\":%.2f}",
                    rs.getString("emp_id"),
                    rs.getString("emp_name"),
                    rs.getString("department"),
                    rs.getDouble("hours_worked"),
                    rs.getDouble("pay_rate"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch export endpoint - reads body as raw SQL filter (legacy)
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }
        String filter = body.toString();

        // Legacy: direct filter append for batch operations
        String batchQuery = "SELECT * FROM payroll_reports WHERE " + filter;
        log.warning("Legacy batch query invoked with filter length: " + filter.length());

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            // Read-only connection mode for safety
            conn.setReadOnly(true);
            ResultSet rs = stmt.executeQuery(batchQuery);
            resp.setContentType("text/csv");
            PrintWriter out = resp.getWriter();
            out.println("emp_id,emp_name,department,hours_worked,pay_rate");
            while (rs.next()) {
                out.printf("%s,%s,%s,%.2f,%.2f%n",
                    rs.getString("emp_id"),
                    rs.getString("emp_name"),
                    rs.getString("department"),
                    rs.getDouble("hours_worked"),
                    rs.getDouble("pay_rate"));
            }
        } catch (SQLException e) {
            log.severe("Batch query failed: " + e.getMessage());
            resp.sendError(500, "Batch export failed");
        }
    }
}
